// Feature strings live in their own files (same row format) so parallel work doesn't collide here.
const TABLE = { ...BASE, ...AGENT_STRINGS, ...WORKSPACE_STRINGS, ...BACKEND_STRINGS, ...SKILLS_STRINGS };
export type Key = keyof typeof TABLE;

const STORAGE_KEY = "tensorizer.lang";

function initialLang(): Lang {
  const fromUrl = new URLSearchParams(window.location.search).get("lang");
  if (fromUrl && LANGS.some((l) => l.code === fromUrl)) return fromUrl as Lang;
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved && LANGS.some((l) => l.code === saved)) return saved as Lang;
  } catch {
    /* storage unavailable */
  }
  return "en"; // first visit: English, whatever the browser's language; the picker remembers a change
}

interface LangState {
  lang: Lang;
  setLang: (lang: Lang) => void;
  t: (key: Key) => string;
}

const LangContext = createContext<LangState | null>(null);

export function LangProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(initialLang);
  // Keep ?lang= in the address bar so a copied link opens in the same language.
  useEffect(() => {
    document.documentElement.lang = lang;
    const url = new URL(window.location.href);
    if (url.searchParams.get("lang") !== lang) {
      url.searchParams.set("lang", lang);
      window.history.replaceState(window.history.state, "", url);
    }
  }, [lang]);
  const setLang = useCallback((next: Lang) => {
    setLangState(next);
    try {
      localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* storage unavailable */
    }
  }, []);
  const value = useMemo<LangState>(() => {
    const index = LANGS.findIndex((l) => l.code === lang);
    // A missing key (e.g. a string not added yet) shows the key itself instead of crashing the page.
    return { lang, setLang, t: (key) => TABLE[key]?.[index] ?? TABLE[key]?.[0] ?? key };
  }, [lang, setLang]);
  return <LangContext.Provider value={value}>{children}</LangContext.Provider>;
}

export function useLang(): LangState {
  const state = useContext(LangContext);
  if (!state) throw new Error("useLang outside LangProvider");
  return state;
}

/** The problem with its text fields swapped for the chosen language where a translation exists. */
export function localize(problem: Problem, lang: Lang): Problem {
  const tr = problem.i18n?.[lang];
  if (!tr) return problem;
  return {
    ...problem,
    title: tr.title ?? problem.title,
    summary: tr.summary ?? problem.summary,
    notes: tr.notes ?? problem.notes,
    translation: problem.translation.map((row, i) => ({ ...row, meaning: tr.meanings?.[i] ?? row.meaning })),
    params: Object.fromEntries(
      Object.entries(problem.params).map(([name, spec]) => [name, { ...spec, label: tr.labels?.[name] ?? spec.label }]),
    ),
  };
}
